class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long answer = 0L;
        int lastInvalid = -1;
        int lastMin = -1;
        int lastMax = -1;

        for (int right = 0; right < nums.length; right++) {
            int value = nums[right];
            if (value < minK || value > maxK) {
                lastInvalid = right;
                lastMin = -1;
                lastMax = -1;
                continue;
            }
            if (value == minK) {
                lastMin = right;
            }
            if (value == maxK) {
                lastMax = right;
            }

            int earliestRequired = Math.min(lastMin, lastMax);
            if (earliestRequired > lastInvalid) {
                answer += earliestRequired - lastInvalid;
            }
        }
        return answer;
    }
}

class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long answer = 0L;
        int segmentStart = 0;
        int left = 0;
        int countMin = 0;
        int countMax = 0;

        for (int right = 0; right < nums.length; right++) {
            int value = nums[right];
            if (value < minK || value > maxK) {
                segmentStart = right + 1;
                left = right + 1;
                countMin = 0;
                countMax = 0;
                continue;
            }
            if (value == minK) {
                countMin++;
            }
            if (value == maxK) {
                countMax++;
            }

            while (countMin > 0 && countMax > 0) {
                if (nums[left] == minK) {
                    countMin--;
                }
                if (nums[left] == maxK) {
                    countMax--;
                }
                left++;
            }
            answer += left - segmentStart;
        }
        return answer;
    }
}

class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long allInside = countRunsInRange(nums, minK, maxK);
        long missingMin = countRunsInRange(nums, (long) minK + 1L, maxK);
        long missingMax = countRunsInRange(nums, minK, (long) maxK - 1L);
        long missingBoth = countRunsInRange(nums, (long) minK + 1L, (long) maxK - 1L);
        return allInside - missingMin - missingMax + missingBoth;
    }

    private long countRunsInRange(int[] nums, long low, long high) {
        if (low > high) {
            return 0L;
        }
        long answer = 0L;
        long runLength = 0L;
        for (int value : nums) {
            if (value >= low && value <= high) {
                runLength++;
                answer += runLength;
            } else {
                runLength = 0L;
            }
        }
        return answer;
    }
}

class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long answer = 0L;
        for (int left = 0; left < nums.length; left++) {
            int minimum = Integer.MAX_VALUE;
            int maximum = Integer.MIN_VALUE;
            for (int right = left; right < nums.length; right++) {
                int value = nums[right];
                minimum = Math.min(minimum, value);
                maximum = Math.max(maximum, value);
                if (minimum < minK || maximum > maxK) {
                    break;
                }
                if (minimum == minK && maximum == maxK) {
                    answer++;
                }
            }
        }
        return answer;
    }
}
